/**
 * Create SLSA Level 3 provenance with GitHub context
 * Enhanced version using GitHubContextExtractor for robust context handling
 */
export function createSLSAProvenance(
  filesManifest: FileManifest,
  githubContext: Context
): SLSAProvenance {
  const buildStartTime = new Date().toISOString();
  
  // Extract and validate GitHub context
  const contextExtractor = new GitHubContextExtractor();
  const contextResult = contextExtractor.extractContext(githubContext);
  
  if (!contextResult.isValid || !contextResult.data) {
    throw new Error(`GitHub context validation failed: ${contextResult.errors.join(', ')}`);
  }

  const gitHubData = contextResult.data;
  
  // Log any warnings
  if (contextResult.warnings.length > 0) {
    console.warn('GitHub context warnings:', contextResult.warnings);
  }

  // Create subject entries for all files with proper digest format
  const subject: SLSASubject[] = filesManifest.files.map(file => ({
    name: file.path,
    digest: {
      sha256: file.content_hash.replace('sha256:', '')
    }
  }));

  // Build repository URI in SLSA format
  const repoUri = GitHubContextExtractor.formatRepositoryUri(gitHubData);
  
  // Ensure buildEndTime is always after buildStartTime to avoid race conditions
  const buildEndTime = new Date(Math.max(new Date().getTime(), new Date(buildStartTime).getTime() + 1)).toISOString();

  const provenance: SLSAProvenance = {
    _type: "https://in-toto.io/Statement/v0.1",
    predicateType: "https://slsa.dev/provenance/v0.2",
    subject,
    predicate: {
      builder: {
        id: "https://github.com/cryptoguard/action@v1.0"
      },
      buildType: "github-actions-tee",
      invocation: {
        configSource: {
          uri: repoUri,
          digest: {
            sha1: gitHubData.sha
          },
          entryPoint: gitHubData.workflow
        },
        parameters: {
          workflow: gitHubData.workflow,
          actor: gitHubData.actor,
          event: gitHubData.eventName,
          ref: gitHubData.ref,
          runId: gitHubData.runId.toString(),
          runAttempt: gitHubData.runAttempt?.toString()
        },
        environment: {
          arch: process.arch,
          container: 'github-actions'
        }
      },
      metadata: {
        buildStartedOn: buildStartTime,
        buildFinishedOn: buildEndTime,
        completeness: {
          parameters: true,  // We capture all parameters
          environment: false, // GitHub Actions environment is not fully captured for security
          materials: true    // We capture source materials
        },
        reproducible: false, // GitHub Actions builds are generally not reproducible due to timestamps and environment
        buildInvocationId: `${gitHubData.repository}-${gitHubData.runId}-${gitHubData.runAttempt || 1}`
      },
      materials: [
        {
          uri: repoUri,
          digest: {
            sha1: gitHubData.sha
          }
        }
      ]
    }
  };

  return provenance;
}

