/**
 * Validate SLSA provenance structure
 */
export function validateSLSAProvenance(provenance: SLSAProvenance, options?: SchemaValidationOptions): boolean {
  const validator = new SLSAProvenanceValidator();
  const result = validator.validateProvenance(provenance, options);
  
  // For backward compatibility, return boolean (consider errors only, not warnings)
  return result.isValid;
}

/**
 * Enhanced SLSA provenance validation with detailed results
 * Returns comprehensive validation information including errors, warnings, and severity
 */
export function validateSLSAProvenanceDetailed(provenance: SLSAProvenance, options: SchemaValidationOptions = {}): ValidationResult {
  const validator = new SLSAProvenanceValidator();
  return validator.validateProvenance(provenance, options);
}

/**
 * Legacy validation function for backward compatibility
 * @deprecated Use validateSLSAProvenance() or validateSLSAProvenanceDetailed() instead
 */
export function validateSLSAProvenanceLegacy(provenance: SLSAProvenance): boolean {
  try {
    // Check required fields
    if (!provenance._type || !provenance.predicateType || !provenance.subject || !provenance.predicate) {
      return false;
    }

    // Validate SLSA v0.2 structure
    if (provenance._type !== "https://in-toto.io/Statement/v0.1") {
      return false;
    }

    if (!['https://slsa.dev/provenance/v0.2', 'https://slsa.dev/provenance/v1'].includes(provenance.predicateType)) {
      return false;
    }

    // Validate subject entries
    if (!Array.isArray(provenance.subject) || provenance.subject.length === 0) {
      return false;
    }

    for (const subj of provenance.subject) {
      if (!subj.name || !subj.digest || !subj.digest.sha256) {
        return false;
      }

      // Validate SHA256 format
      if (!/^[a-fA-F0-9]{64}$/.test(subj.digest.sha256)) {
        return false;
      }
    }

    // Validate predicate structure
    const { predicate } = provenance;
    if (!predicate.builder || !predicate.builder.id) {
      return false;
    }

    if (!predicate.buildType) {
      return false;
    }

    if (!predicate.invocation || !predicate.invocation.configSource) {
      return false;
    }

    if (!predicate.metadata) {
      return false;
    }

    if (!Array.isArray(predicate.materials)) {
      return false;
    }

    return true;

  } catch (error) {
    return false;
  }
}

/**
 * Generate provenance fingerprint for verification
 */
export function generateProvenanceFingerprint(provenance: SLSAProvenance): string {
  const crypto = require('crypto');
  
  // Create canonical JSON by recursively sorting all object keys
  function canonicalize(obj: any): any {
    if (obj === null || typeof obj !== 'object') {
      return obj;
    }
    
    if (Array.isArray(obj)) {
      return obj.map(canonicalize);
    }
    
    const sortedKeys = Object.keys(obj).sort();
    const canonical: any = {};
    for (const key of sortedKeys) {
      canonical[key] = canonicalize(obj[key]);
    }
    return canonical;
  }
  
  const canonicalProvenance = canonicalize(provenance);
  const canonicalJson = JSON.stringify(canonicalProvenance);
  return crypto.createHash('sha256').update(canonicalJson).digest('hex');
}

// TEE Attestation Module Interfaces and Implementation

export interface TEEAttestationConfig {
  endpoint: string;
  region: string;
  privateKey: string;
  timeout?: number;
  retryLimit?: number;
}

export interface TEEAttestationRequest {
  provenance: SLSAProvenance;
  requestId: string;
  timestamp: string;
  signature: string;
}

export interface TEEAttestationResponse {
  success: boolean;
  tee_signature: string;
  attestation_timestamp: string;
  hardware_evidence: string;
  attestation_document: string;
  error?: string;
}

export interface TEEAttestationResult {
  success: boolean;
  teeSignature?: string;
  attestationTimestamp?: string;
  hardwareEvidence?: string;
  attestationDocument?: string;
  requestId?: string;
  error?: string;
}

/**
 * TEEAttestationClient handles secure communication with TEE services
 * for hardware attestation of SLSA provenance documents
 */
export class TEEAttestationClient {
  private config: TEEAttestationConfig;
  private readonly DEFAULT_TIMEOUT = 30000; // 30 seconds
  private readonly DEFAULT_RETRY_LIMIT = 3;
  private readonly BASE_RETRY_DELAY = 1000; // 1 second

  constructor(config: TEEAttestationConfig) {
    this.validateConfig(config);
    this.config = {
      ...config,
      timeout: config.timeout || this.DEFAULT_TIMEOUT,
      retryLimit: config.retryLimit || this.DEFAULT_RETRY_LIMIT
    };
  }

  /**
   * Send SLSA provenance to TEE for hardware attestation
   */
  async sendForAttestation(provenance: SLSAProvenance): Promise<TEEAttestationResult> {
    const requestId = this.generateRequestId();
    const timestamp = new Date().toISOString();

    try {
      // Create canonical JSON for signing
      const canonicalProvenance = this.canonicalizeProvenance(provenance);
      const message = JSON.stringify({
        provenance: canonicalProvenance,
        requestId,
        timestamp
      });

      // Sign the request
      const signature = await signMessage(message, this.config.privateKey);

      const request: TEEAttestationRequest = {
        provenance,
        requestId,
        timestamp,
        signature
      };

      // Execute request with retry logic
      const response = await this.executeWithRetry(request);

      if (!response.success) {
        return {
          success: false,
          error: response.error || 'TEE attestation failed'
        };
      }

      // Verify the TEE response signature
      const verificationResult = await this.verifyTEEResponse(response);
      if (!verificationResult.success) {
        return {
          success: false,
          error: `TEE response verification failed: ${verificationResult.error}`
        };
      }

      return {
        success: true,
        teeSignature: response.tee_signature,
        attestationTimestamp: response.attestation_timestamp,
        hardwareEvidence: response.hardware_evidence,
        attestationDocument: response.attestation_document,
        requestId
      };

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      return {
        success: false,
        error: `TEE attestation failed: ${errorMessage}`
      };
    }
  }

  /**
   * Execute TEE request with exponential backoff retry logic
   */
  private async executeWithRetry(request: TEEAttestationRequest): Promise<TEEAttestationResponse> {
    let lastError: Error | null = null;

    for (let attempt = 1; attempt <= this.config.retryLimit!; attempt++) {
      try {
        return await this.executeTEERequest(request);
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));
        
        if (attempt === this.config.retryLimit) {
          throw lastError;
        }

        // Exponential backoff with jitter
        const delay = this.BASE_RETRY_DELAY * Math.pow(2, attempt - 1) + Math.random() * 1000;
        console.warn(`TEE attestation attempt ${attempt} failed, retrying in ${delay}ms:`, lastError.message);
        await this.sleep(delay);
      }
    }

    throw lastError || new Error('Max retries exceeded');
  }

  /**
   * Execute actual TEE service request
   * Note: This is a mock implementation for the demo
   * In production, this would make HTTPS requests to actual TEE service endpoints
   */
  private async executeTEERequest(request: TEEAttestationRequest): Promise<TEEAttestationResponse> {
    // Simulate network delay
    await this.sleep(100 + Math.random() * 200);

    // Mock TEE service response
    // In production, this would be an HTTPS POST to the TEE service
    const mockTEEPrivateKey = 'tee_private_key_placeholder_for_testing_only';
    const attestationMessage = `tee_attest:${request.requestId}:${request.timestamp}`;
    const teeSignature = await signMessage(attestationMessage, mockTEEPrivateKey);

    return {
      success: true,
      tee_signature: teeSignature,
      attestation_timestamp: new Date().toISOString(),
      hardware_evidence: `tee_evidence_${this.config.region}_${Date.now()}`,
      attestation_document: `tee_doc_${request.requestId}_${this.config.region}`
    };
  }

  /**
   * Verify TEE service response signature
   * Note: In production, this would use the TEE service's public key
   */
  private async verifyTEEResponse(response: TEEAttestationResponse): Promise<{ success: boolean; error?: string }> {
    try {
      // In production, verify using actual TEE public key
      // For now, we'll assume the response is valid if it has required fields
      if (!response.tee_signature || !response.attestation_timestamp || !response.hardware_evidence) {
        return {
          success: false,
          error: 'Missing required fields in TEE response'
        };
      }

      return { success: true };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : String(error)
      };
    }
  }

  /**
   * Generate unique request ID for attestation tracking
   */
  private generateRequestId(): string {
    const timestamp = Date.now().toString();
    const random = Math.random().toString(36).substr(2, 9);
    return `attest_${timestamp}_${random}`;
  }

  /**
   * Create canonical JSON representation of provenance for consistent hashing
   */
  private canonicalizeProvenance(provenance: SLSAProvenance): any {
    function canonicalize(obj: any): any {
      if (obj === null || typeof obj !== 'object') {
        return obj;
      }
      
      if (Array.isArray(obj)) {
        return obj.map(canonicalize);
      }
      
      const sortedKeys = Object.keys(obj).sort();
      const canonical: any = {};
      for (const key of sortedKeys) {
        canonical[key] = canonicalize(obj[key]);
      }
      return canonical;
    }
    
    return canonicalize(provenance);
  }

  /**
   * Validate TEE attestation configuration
   */
  private validateConfig(config: TEEAttestationConfig): void {
    if (!config.endpoint || typeof config.endpoint !== 'string') {
      throw new Error('TEE endpoint is required and must be a valid URL');
    }

    if (!config.region || typeof config.region !== 'string') {
      throw new Error('TEE region is required and must be a non-empty string');
    }

    if (!config.privateKey || typeof config.privateKey !== 'string') {
      throw new Error('Private key is required for TEE authentication');
    }

    if (config.timeout && (typeof config.timeout !== 'number' || config.timeout <= 0)) {
      throw new Error('Timeout must be a positive number');
    }

    if (config.retryLimit && (typeof config.retryLimit !== 'number' || config.retryLimit < 1 || config.retryLimit > 10)) {
      throw new Error('Retry limit must be between 1 and 10');
    }
  }

  /**
   * Sleep utility for retry delays
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}